from typing import List

class Solution:
    def minJumpCost(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [float('inf')] * n
        dp[0] = 0

        # dp[j]: min cost to reach j from 0
        for i in range(n):
            if dp[i] == float('inf'):
                continue
            for j in range(i + 1, n):
                if nums[j] >= nums[i]:
                    cost = (j - i) * (j - i)
                    dp[j] = min(dp[j], dp[i] + cost)

        return dp[n - 1] if dp[n - 1] != float('inf') else -1
