#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minJumpCost(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> dp(n, INT_MAX);
        dp[0] = 0;

        for (int i = 0; i < n; ++i) {
            if (dp[i] == INT_MAX) continue;
            for (int j = i + 1; j < n; ++j) {
                if (nums[j] >= nums[i]) {
                    int cost = (j - i) * (j - i);
                    dp[j] = std::min(dp[j], dp[i] + cost);
                }
            }
        }
        return dp[n - 1] == INT_MAX ? -1 : dp[n - 1];
    }
};

import java.util.*;

class Solution {
    public int minJumpCost(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            if (dp[i] == Integer.MAX_VALUE) continue;
            for (int j = i + 1; j < n; j++) {
                if (nums[j] >= nums[i]) {
                    int cost = (j - i) * (j - i);
                    dp[j] = Math.min(dp[j], dp[i] + cost);
                }
            }
        }
        return dp[n - 1] == Integer.MAX_VALUE ? -1 : dp[n - 1];
    }
}

var minJumpCost = function(nums) {
    const n = nums.length;
    const dp = new Int32Array(n).fill(Infinity);
    dp[0] = 0;

    for (let i = 0; i < n; i++) {
        if (dp[i] === Infinity) continue;
        for (let j = i + 1; j < n; j++) {
            if (nums[j] >= nums[i]) {
                const cost = (j - i) * (j - i);
                dp[j] = Math.min(dp[j], dp[i] + cost);
            }
        }
    }
    return dp[n - 1] === Infinity ? -1 : dp[n - 1];
};
